        icd_retries = iter(self.RetryManager(fatal=raise_for_incomplete))
        icd_rm = next(icd_retries)
        main_retries = iter(self.RetryManager())
        main_rm = next(main_retries)



        while True:
            try:
                response = self._call_api(
                    ep=ep, fatal=True, headers=headers,
