            "object_id": data_source.id,
            "object_type": "data_source",
            "query": query_text,
            "query_id": query_id,
            "parameters": parameters,
        },
    )

    if query_result:
        return {
            "query_result": serialize_query_result(
                query_result, current_user.is_api_user()
            )
        }
    else:
        job = enqueue_query(
