            cnames = statement.column_names()

            rows = [dict(zip(cnames, row)) for row in statement]
            data = {"columns": columns, "rows": rows}
            json_data = json_dumps(data)
        finally:
            if statement is not None:
                statement.close()

            connection.close()

        return json_data, error
