        def ensureBytes(s):
            return s.encode("ascii") if isinstance(s, str) else s

        def generateWWWAuthenticate(scheme, challenge):
            lst = []
            for k, v in challenge.items():
                k = ensureBytes(k)
                v = ensureBytes(v)
                lst.append(k + b"=" + quoteString(v))
