def get_serializer_for_model(model, prefix=""):
    """
    Dynamically resolve and return the appropriate serializer for a model.

    Raises:
        SerializerNotFound: if the requested serializer cannot be located.
    """
    app_name, model_name = model._meta.label.split(".")
    if app_name == "contenttypes" and model_name == "ContentType":
        app_name = "extras"

    if app_name == "auth":
        app_name = "users"
    serializer_name = f"{app_name}.api.serializers.{prefix}{model_name}Serializer"
    if app_name not in settings.PLUGINS:
        serializer_name = f"nautobot.{serializer_name}"
    try:
        return dynamic_import(serializer_name)
    except AttributeError as exc:
        raise exceptions.SerializerNotFound(
            f"Could not determine serializer for {app_name}.{model_name} with prefix '{prefix}'"
        ) from exc
def run_app(**kwargs):
    sys_args = sys.argv


    runner_name = os.path.basename(sys_args[0])

    default_config_path = kwargs.get("default_config_path")


    parser = management.CommandParser(
        description=kwargs.pop("description"),
        formatter_class=VerboseHelpFormatter,
        add_help=False,
    )
    parser.add_argument(
        "-c",
        "--config",
        metavar="CONFIG",
        help="Path to the configuration file",
    )
    parser.add_argument(
        "--version",
        action="version",
        version=__version__,
    )







    args, unparsed_args = parser.parse_known_args()


    subparsers = parser.add_subparsers(help=False, dest="command", metavar="")
    init_parser = subparsers.add_parser(
        "init",
        help="Initialize a new configuration",
    )
    init_parser.add_argument(
        "--disable-installation-metrics",
        action="store_true",
        help="Disable sending of anonymized installation metrics for this configuration.",
    )
    init_parser.add_argument(
        "config_path",
        default=default_config_path,
        nargs="?",
        help="Path to output generated configuration file",
    )


    try:
        args = parser.parse_args()
        command = args.command
        command_args = sys.argv[1:]



    except management.CommandError as err:
        if "invalid choice" not in str(err):
            raise


        sys_args = sys_args[:1] + unparsed_args
        _, command, command_args = parse_command_args(sys_args[1:])


    if not command:
        parser.print_help()
        parser.exit(1)


    if command == "init":
        settings_initializer = kwargs.get("settings_initializer")

        config_path = os.path.expanduser(args.config_path)


        if os.path.exists(config_path):
            print(
                f"A configuration already exists at {config_path}. Please backup and remove it or choose another path."
            )
            return

        if not sys.__stdin__.isatty():

            installation_metrics_enabled = not args.disable_installation_metrics
        elif args.disable_installation_metrics is True:

            installation_metrics_enabled = False
        else:

            installation_metrics_enabled = None
            while installation_metrics_enabled is None:
                installation_metrics_prompt = input(
                    "Nautobot would like to send anonymized installation metrics to the project's maintainers.\n"
                    "These metrics include the installed Nautobot version, the Python version in use, an anonymous "
                    '"deployment ID", and a list of one-way-hashed names of enabled Nautobot Apps and their versions.\n'
                    "Allow Nautobot to send these metrics? [y/n]: "
                )
                try:
                    installation_metrics_enabled = is_truthy(installation_metrics_prompt)
                except ValueError:
                    print("Please enter 'y' or 'n'.")

        if installation_metrics_enabled:
            print("Installation metrics will be sent when running 'nautobot-server post_upgrade'. Thank you!")
        else:
            print("Installation metrics will not be sent by default.")


        try:
            create_default_settings(
                config_path, settings_initializer, installation_metrics_enabled=installation_metrics_enabled
            )
        except OSError as e:
            raise e.__class__(f"Unable to write default settings file to {config_path}")

        print(f"Configuration file created at {config_path}")

        return




    config_path = args.config


    try:
        configure_app(config_path=config_path, **kwargs)
    except ValueError as err:
        parser.exit(status=2, message=str(err) + "\n")


    management.execute_from_command_line([runner_name, command] + command_args)


    sys.exit(0)
