            sizeC = max(len(map_json), sizeC)
            for c in range(sizeC):
                enabled = None
                if len(map_json) > c:
                    m = map_json[c].get(name)

                    if m is not None:
                        enabled = m.get("enabled") in (True, "true")
                codomains.append(enabled)
        except Exception:
            logger.debug("Invalid json for query ?maps=%s" % map_json)
            codomains = None
    return codomains
