        shape["y2"] = int(s.getY2().getValue())
        x = min(shape["x1"], shape["x2"])
        y = min(shape["y1"], shape["y2"])
        bBox = (
            x,
            y,
            max(shape["x1"], shape["x2"]) - x,
            max(shape["y1"], shape["y2"]) - y,
        )
    elif type(s) == omero.model.PointI:
        shape["type"] = "Point"
