class ZopeIterator(Iterator):
    def index(self):
        return super().index()
    def start(self):
        return super().start()
    def end(self):
        return super().end()
    def item(self):
        return super().item()
    def first(self, name=None):
        if self.start:
            return True
        return not self.same_part(name, self._last_item, self.item)
    def last(self, name=None):
        if self.end:
            return True
        return not self.same_part(name, self.item, self._next)
    def same_part(self, name, ob1, ob2):
        if name is None:
            return ob1 == ob2
        no = object()
        return getattr(ob1, name, no) == getattr(ob2, name, no) is not no
    def __next__(self):
        if self._nextIndex > 0:
            self._last_item = self.item
        return super().__next__()
    def next(self):
        if self._nextIndex > 0:
            self._last_item = self.item
        return super().next()
class PathIterator(ZopeIterator):
    def traverse(self, name, furtherPath):
        if name in ('first', 'last'):
            method = getattr(self, name)


            name = furtherPath[:]
            if not name:
                name = None

            furtherPath[:] = []
            return method(name)
        return getattr(self, name)
    def same_part(self, name, ob1, ob2):
        if name is None:
            return ob1 == ob2
        if isinstance(name, str):
            name = name.split('/')
        elif isinstance(name, bytes):
            name = name.split(b'/')
        try:
            ob1 = boboAwareZopeTraverse(ob1, name, None)
            ob2 = boboAwareZopeTraverse(ob2, name, None)
        except ZopeUndefs:
            return False
        return ob1 == ob2
