            return jsonify({"message": str(e)}), 400

        file_path = safe_join(root_dir_path, path[1:])

        if not file_path.split(".")[-1] in _config.ALLOWED_FILE_EXTENSIONS:
            return jsonify({"message": "Given file type is not supported."}), 409

