    if is_authenticated():
        return flask.redirect(next)

    if api.get_config_value("webui", "autologin"):
        allusers = api.get_all_userdata()
        if len(allusers) == 1:
            user_info = list(allusers.values())[0]
            set_session(user_info)


            if is_authenticated():
                return flask.redirect(next)

    return render_template("login.html", next=next)
