def handle_404(exc):
    flask.current_app.logger.debug("Error 404 - Requested URL: {}".format(flask.request.base_url))
    messages = [f"Error {exc.code}: {exc.description}"]
    return render_template('error.html', messages=messages), 404
def handle_error(exc):
    tb = traceback.format_exc()
    try:
        code = exc.code
        desc = exc.desc
    except AttributeError:
        code = 500
        desc = exc

    flask.current_app.logger.debug(exc, exc_info=True)

    messages = [f"Error {code}: {desc}"]
    messages.extend(tb.split('\n'))
    return render_template("error.html", messages=messages), code
ERROR_HANDLERS = [(Exception, handle_error), (404, handle_404)]

def is_safe_url(location):
    ref_url = urlparse(flask.request.host_url)
    test_url = urlparse(urljoin(flask.request.host_url, location))
    return ref_url.netloc == test_url.netloc
def get_redirect_url(fallback=None):
    login_url = urljoin(flask.request.url_root, flask.url_for('app.login'))
    for location in flask.request.values.get("next"), flask.request.referrer:
        if not location:
            continue
        if location in (flask.request.url, login_url):
            continue
        if is_safe_url(location):
            return location
    return fallback
