            self, role, groups, notroles,
            roles, parentroles, usedgroups):



        if role in notroles:
            return False





        if not (role in parentroles or role in roles):
            for b in self.roles[role]['backends_groups']:
                for g in self.roles[role]['backends_groups'][b]:
                    if b not in groups:
                        notroles.add(role)
