        kwargs = self._build_kwargs(kwargs, batch, batch_idx)

        self.batch_progress.increment_ready()


        self._on_evaluation_batch_start(**kwargs)

        self.batch_progress.increment_started()


        output = self._evaluation_step(**kwargs)
